package com.ngtintoreria.erp.pricing;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="price_lists")
public class PriceList {
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,unique=true,length=60) private String code; @Column(nullable=false,length=180) private String name; private UUID clientId; @Column(nullable=false,length=3) private String currency="PEN"; @Column(nullable=false) private LocalDate validFrom; private LocalDate validTo; @Column(nullable=false) private int priority=100; @Column(nullable=false) private boolean active=true; @Column(nullable=false,updatable=false) private OffsetDateTime createdAt; @Column(nullable=false) private OffsetDateTime updatedAt; @PrePersist void pre(){createdAt=updatedAt=OffsetDateTime.now();} @PreUpdate void upd(){updatedAt=OffsetDateTime.now();}
 public UUID getId(){return id;} public String getCode(){return code;} public void setCode(String v){code=v;} public String getName(){return name;} public void setName(String v){name=v;} public UUID getClientId(){return clientId;} public void setClientId(UUID v){clientId=v;} public String getCurrency(){return currency;} public void setCurrency(String v){currency=v;} public LocalDate getValidFrom(){return validFrom;} public void setValidFrom(LocalDate v){validFrom=v;} public LocalDate getValidTo(){return validTo;} public void setValidTo(LocalDate v){validTo=v;} public int getPriority(){return priority;} public void setPriority(int v){priority=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} public OffsetDateTime getCreatedAt(){return createdAt;} public OffsetDateTime getUpdatedAt(){return updatedAt;}
}
